<?php
require_once __DIR__.'/Ehsan.php';
/** Content planning uses the same guarded job/credit runner as Ehsan. No AI-written final content. */
class Aria extends Ehsan {
    protected const EMPLOYEE='aria';
    public const CHANNELS=['website'=>'وب‌سایت','instagram_post'=>'اینستاگرام / پست','instagram_story'=>'اینستاگرام / استوری','telegram'=>'تلگرام','bale'=>'بله','rubika'=>'روبیکا','sms'=>'پیامک'];
    protected static function need($p,$write=false){$a=parent::need($p,$write);AiAccess::need('calendar',$write?'use':'view');return $a;}
    private static function epoch($p,$row){if((int)($row['recovery_revision']??0)!==(int)($p['settings']['data_recovery_revision']??0))throw new RuntimeException('پس از بازیابی، برنامه و مجوزهای قبلی قابل اجرا نیستند؛ برنامهٔ تازه لازم است.');}
    public static function day($value){$d=is_string($value)?DateTimeImmutable::createFromFormat('!Y-m-d',$value,new DateTimeZone('Asia/Tehran')):false;if(!$d||$d->format('Y-m-d')!==$value)throw new RuntimeException('تاریخ میلادی معتبر لازم است.');return $d;}
    protected function configuration($p,$row,$input){
        $channels=array_values(array_unique((array)($input['channels']??[])));$auto=array_values(array_unique((array)($input['auto_publish']??[])));$count=(int)($input['count']??0);$start=self::day($input['start']??'');
        if(!$channels||array_diff($channels,array_keys(self::CHANNELS))||array_diff($auto,$channels)||in_array('sms',$auto,true)||$count<1||$count>20||$start->getTimestamp()<strtotime('today')||$start->getTimestamp()>time()+366*86400||array_diff($row['frequencies'],['weekly','monthly']))throw new RuntimeException('کانال، تاریخ آغاز، تعداد ۱ تا ۲۰ و دورهٔ هفتگی/ماهانه را بررسی کنید. پیامک همیشه تأیید مستقل دارد.');
        $members=array_column($p['users']??[],'username');$roles=[];foreach(['writer','designer','reviewer'] as $role){$names=array_values(array_unique((array)($input[$role]??[])));if(count($names)>30||array_diff($names,$members))throw new RuntimeException('مسئول باید از اعضای همین پروژه انتخاب شود.');$roles[$role]=$names;}
        return array_replace($row,['channels'=>$channels,'auto_publish'=>$auto,'count'=>$count,'start'=>$start->format('Y-m-d'),'roles'=>$roles,'auto_tasks'=>false]);
    }
    protected function jobConfig($config,$frequency,$slot){if(!is_array($config))throw new RuntimeException('ابتدا تنظیمات آریا را ثبت کنید.');if(!in_array($frequency,['weekly','monthly'],true))throw new RuntimeException('دورهٔ آریا هفتگی یا ماهانه است.');if($slot!==null)$config['start']=date('Y-m-d',(int)$slot);$start=self::day($config['start']);$config['end']=$frequency==='weekly'?$start->modify('+6 days')->format('Y-m-d'):date('Y-m-d',SaaSAccounts::extendExpiry($start->getTimestamp(),'monthly')-1);return $config;}
    public function snapshot($p,$frequency){
        $data=parent::snapshot($p,$frequency);$known=array_column(array_column($data['sources'],'source'),'id');$rows=[];
        foreach((new Ehsan($this->accounts))->jobs($p) as $j){if(($j['state']??'')!=='done'||empty($j['report'])||!empty($j['task_paused_by_recovery']))continue;$rows[]=['id'=>$j['id'],'at'=>$j['completed_at']??$j['at'],'summary'=>$j['report']['summary'],'actions'=>$j['report']['actions'],'limitations'=>$j['report']['limitations']];break;}
        $data['calendar_overview']=(new AiData(new AiStore()))->read($p,'calendar',[],0,100);$data['ehsan_reports']=$rows;if(!$rows)$data['limitations'][]='گزارش مجاز و قابل استفادهٔ احسان موجود نیست؛ برنامه با داده‌های موجود پیشنهاد می‌شود.';
        $visible=[];foreach($this->jobs($p) as $job)if(!empty($job['report'])&&empty($job['task_paused_by_recovery']))$visible[$job['id']]=true;$data['approved_plans']=[];foreach(array_slice($p['settings']['aria_calendar']['plans']??[],-3,true) as $id=>$plan)if(isset($visible[$id]))$data['approved_plans'][]=['id'=>$id,'state'=>$plan['state'],'start'=>$plan['start'],'end'=>$plan['end'],'entries'=>array_map(static fn($e)=>array_intersect_key($e,array_flip(['title','channel','publish_at','state'])),$plan['entries'])];$data['limitations'][]='آمار عملکرد شبکه‌های اجتماعی و مناسبت‌ها فقط در صورت وجود منبع واقعی قابل استناد است؛ مناسبت، فروش یا نتیجهٔ انتشار را نساز.';
